package main

import "fmt"

// Only the last parameter may be ...T.
func Sum(nums ...int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

func main() {
	fmt.Println(Sum(1, 2, 3)) // pass any number of ints
	// Output: 6
}

