package main

import "fmt"

// level is fixed and required; args is the variadic tail.
func Logf(level, format string, args ...any) {
	fmt.Printf("[%s] "+format+"\n", append([]any{}, args...)...)
	_ = level
}

func main() {
	fmt.Printf("[INFO] user %d did %s\n", 42, "login")
	// Output: [INFO] user 42 did login
}

