package main

import "fmt"

func zeroFirst(xs ...int) {
	if len(xs) > 0 {
		xs[0] = 0 // mutates the caller's backing array
	}
}

func main() {
	s := []int{7, 8, 9}
	zeroFirst(s...) // shares s's array
	fmt.Println(s)
	// Output: [0 8 9]
}

