func TestMax(t *testing.T) {
	cases := []struct {
		in     []int
		want   int
		wantOK bool
	}{
		{[]int{3, 1, 4, 1, 5}, 5, true},
		{[]int{-7}, -7, true},
		{[]int{}, 0, false},
	}
	for _, c := range cases {
		got, ok := Max(c.in...) // spread the test slice into the variadic param
		if got != c.want || ok != c.wantOK {
			t.Errorf("Max(%v)=(%d,%v) want (%d,%v)", c.in, got, ok, c.want, c.wantOK)
		}
	}
}

